/** A NBA card */
export type NbaCard = AnyCardInterface & Node & WithSubscriptionsInterface & {
  readonly __typename?: 'NBACard';
  readonly activeSuspensions: ReadonlyArray<Suspension>;
  readonly activeTaskAppearances: ReadonlyArray<TaskAppearanceInterface>;
  readonly anyPlayer: AnyPlayerInterface;
  readonly anyPositions: ReadonlyArray<Position>;
  readonly anyTeam: TeamInterface;
  readonly assetId: Scalars['ID']['output'];
  readonly availableCardBoosts: ReadonlyArray<CardBoost>;
  readonly averageScore?: Maybe<Scalars['Float']['output']>;
  readonly backPictureUrl: Scalars['String']['output'];
  readonly basketballPlayer: NbaPlayer;
  readonly blueprint?: Maybe<Blueprint>;
  readonly bonuses: ReadonlyArray<So5AppearanceBonusInterface>;
  readonly bonusesAfterTransfer: ReadonlyArray<So5AppearanceBonusInterface>;
  readonly borderRadius: Scalars['Int']['output'];
  readonly cardBackgroundUrl?: Maybe<Scalars['String']['output']>;
  readonly cardBackgroundVideoUrl?: Maybe<Scalars['String']['output']>;
  readonly cardCollectionCards: ReadonlyArray<CardCollectionCard>;
  readonly cardEditionName?: Maybe<Scalars['String']['output']>;
  /** @deprecated Not used anymore */
  readonly cardPrice?: Maybe<Scalars['Int']['output']>;
  readonly cardSet?: Maybe<CardSet>;
  readonly cardStats?: Maybe<CardStats>;
  readonly collection?: Maybe<Collection>;
  readonly collectionIncreaseScoreBreakdownAfterTransfer?: Maybe<CardCollectionCardScoreBreakdown>;
  readonly collectionScoringMatrix: ReadonlyArray<CardCollectionScoringMatrix>;
  readonly concurrentSo5Lineups: ReadonlyArray<So5Lineup>;
  readonly contractAddress?: Maybe<Scalars['EthereumAddress']['output']>;
  readonly currentUserSubscription?: Maybe<EmailSubscription>;
  readonly decks: ReadonlyArray<Deck>;
  readonly delayedReveal?: Maybe<Scalars['Boolean']['output']>;
  readonly displayRarity: Scalars['String']['output'];
  readonly dropRank?: Maybe<Scalars['Int']['output']>;
  readonly eligibleBoards: ReadonlyArray<Board>;
  readonly eligiblePlayerGameScores: ReadonlyArray<PlayerGameScoreInterface>;
  readonly eligibleUpcomingLeagueTracks: ReadonlyArray<So5LeagueTrack>;
  readonly ethereumId: Scalars['String']['output'];
  readonly ethereumOwner?: Maybe<TokenOwner>;
  readonly formattedCardEditionName?: Maybe<Scalars['String']['output']>;
  /** Current card level */
  readonly grade: Scalars['Int']['output'];
  readonly gradeAfterTransfer: Scalars['Int']['output'];
  readonly id: Scalars['ID']['output'];
  readonly inSeasonEligible: Scalars['Boolean']['output'];
  readonly inSeasonUntil?: Maybe<Scalars['ISO8601DateTime']['output']>;
  readonly ipfsPictureUrl?: Maybe<Scalars['String']['output']>;
  readonly ipfsUrl?: Maybe<Scalars['String']['output']>;
  readonly lastLeveledUpAt?: Maybe<Scalars['ISO8601DateTime']['output']>;
  readonly latestEnglishAuction?: Maybe<TokenAuction>;
  readonly latestPrimaryOffer?: Maybe<TokenPrimaryOffer>;
  readonly levelUpAppliedCount: Scalars['Int']['output'];
  readonly livePrimaryOffer?: Maybe<TokenPrimaryOffer>;
  readonly liveSingleBuyOffers: ReadonlyArray<TokenOffer>;
  readonly liveSingleSaleOffer?: Maybe<TokenOffer>;
  /** So5Lineup that this card is being used in for the live So5Fixture */
  readonly liveSo5Lineup?: Maybe<So5Lineup>;
  readonly loanedToken?: Maybe<LoanedToken>;
  /** Returns the lowest price card of the same player, rarity and season */
  readonly lowestPriceCard?: Maybe<AnyCardInterface>;
  /** Returns the lowest price card of the same player and rarity */
  readonly lowestPriceCardAnySeason?: Maybe<AnyCardInterface>;
  readonly maxLevelUpAppliedCount: Scalars['Int']['output'];
  readonly myCardCollectionSlot?: Maybe<UserCardCollectionSlot>;
  readonly myMintedSingleSaleOffer?: Maybe<TokenOffer>;
  readonly name: Scalars['String']['output'];
  readonly nextLevelUpAvailableAt?: Maybe<Scalars['ISO8601DateTime']['output']>;
  /** So5Lineups that this card is being used in for the opened So5Fixtures */
  readonly openedSo5Lineups: ReadonlyArray<So5Lineup>;
  readonly ownerSince?: Maybe<Scalars['ISO8601DateTime']['output']>;
  readonly ownershipHistory: ReadonlyArray<TokenOwner>;
  readonly pack?: Maybe<Pack>;
  readonly pendingWithdrawal?: Maybe<TokenWithdrawal>;
  readonly pictureUrl?: Maybe<Scalars['String']['output']>;
  /** @deprecated Player loyalty is no longer used */
  readonly playerLoyaltyBoost: RewardBoost;
  /** Total card bonus (XP + Season bonus) */
  readonly power: Scalars['String']['output'];
  /** Total card bonus after transfer */
  readonly powerAfterTransfer: Scalars['String']['output'];
  readonly powerBreakdown: PowerBreakdown;
  readonly powerMalusAfterTransfer: Scalars['String']['output'];
  readonly previouslyOwnedCard?: Maybe<Scalars['Boolean']['output']>;
  readonly previouslyOwnedPlayer?: Maybe<Scalars['Boolean']['output']>;
  readonly priceRange?: Maybe<Range>;
  readonly privateMinPrices?: Maybe<MonetaryAmount>;
  readonly publicMinPrices?: Maybe<MonetaryAmount>;
  readonly rarityTyped: Rarity;
  /**
   * The `related_card_edition_slots` field cannot be nested within a list.
   * @deprecated Use myCardCollectionSlot.relatedCardEditionSlots instead
   */
  readonly relatedCardEditionSlots?: Maybe<ReadonlyArray<UserCardCollectionSlot>>;
  readonly revealableCardCampaign?: Maybe<RevealableCardCampaign>;
  readonly sealable: Scalars['Boolean']['output'];
  readonly sealableFor?: Maybe<Scalars['Int']['output']>;
  readonly sealed: Scalars['Boolean']['output'];
  readonly sealedAt?: Maybe<Scalars['ISO8601DateTime']['output']>;
  readonly sealedFor?: Maybe<Scalars['Int']['output']>;
  /** @deprecated Player loyalty is no longer used */
  readonly sealedPlayerLoyaltyBoost: RewardBoost;
  readonly seasonYear: Scalars['Int']['output'];
  readonly secondaryMarketFeeEnabled: Scalars['Boolean']['output'];
  /**
   * Returns all live or minted offers where this token is included in the sender
   * side. Returns only if authenticated and sender of the offers.
   */
  readonly sentInLiveOffers?: Maybe<ReadonlyArray<TokenOffer>>;
  readonly serialNumber: Scalars['Int']['output'];
  /** @deprecated Not used anymore */
  readonly signedAddCardPrice?: Maybe<SignedCardPrice>;
  readonly signedDropCardPrice?: Maybe<SignedCardPrice>;
  readonly singleCivilYear: Scalars['Boolean']['output'];
  readonly skinEdition?: Maybe<SkinEdition>;
  readonly slug: Scalars['String']['output'];
  readonly solanaAddress?: Maybe<Scalars['String']['output']>;
  readonly solanaBlockExplorerUrl?: Maybe<Scalars['String']['output']>;
  readonly specialEdition?: Maybe<Scalars['String']['output']>;
  readonly sport: Sport;
  readonly sportSeason: SportSeason;
  readonly subscriptionsCount: Scalars['Int']['output'];
  readonly supply: Scalars['Int']['output'];
  readonly threeDimensional: Scalars['Boolean']['output'];
  readonly threeDimensionalAsset?: Maybe<ThreeDimensionalAsset>;
  readonly tokenOwner?: Maybe<TokenOwner>;
  readonly tradeableStatus: Tradeable;
  readonly unsealableAt?: Maybe<Scalars['ISO8601DateTime']['output']>;
  readonly unsealedAt?: Maybe<Scalars['ISO8601DateTime']['output']>;
  /** @deprecated Player loyalty is no longer used */
  readonly unsealedPlayerLoyaltyBoost: RewardBoost;
  readonly usedIn?: Maybe<CardUsageInterface>;
  readonly user?: Maybe<User>;
  readonly videoUrl?: Maybe<Scalars['String']['output']>;
  readonly walletStatus: WalletStatus;
  readonly xp: Scalars['Int']['output'];
  readonly xpAfterTransfer: Scalars['Int']['output'];
  /** XP start range of current card level */
  readonly xpNeededForCurrentGrade: Scalars['Int']['output'];
  /** XP end range of current card level */
  readonly xpNeededForNextGrade?: Maybe<Scalars['Int']['output']>;
};


