  readonly anyPositions: ReadonlyArray<Position>;
  /** Returns the 3 most followed players in the player's club The `any_related_players` field cannot be nested within a list. */
  readonly anyRelatedPlayers: ReadonlyArray<AnyPlayerInterface>;
  /** The `any_so5_average_last_score` field cannot be nested within a list. */
  readonly anySo5AverageLastScore?: Maybe<AverageLastScoreInterface>;
  readonly appearances: Scalars['Int']['output'];
  readonly avatarPictureUrl: Scalars['String']['output'];
  readonly averageScore?: Maybe<Scalars['Float']['output']>;
  readonly averageStats?: Maybe<Scalars['Float']['output']>;
  readonly beforeLastOwningMembership?: Maybe<Membership>;
  readonly birthDay?: Maybe<Scalars['ISO8601Date']['output']>;
  readonly cardPositions: ReadonlyArray<Position>;
  /** @deprecated Not used anymore */
  readonly cardPrice?: Maybe<Scalars['Int']['output']>;
  /** Cards of this player that are owned by a manager. Updated once a day. */
  readonly cardSupply: ReadonlyArray<CardSeasonSupply>;
  readonly careerSeasons: ReadonlyArray<Season>;
  readonly clubMemberships: ReadonlyArray<Membership>;
